<?php
declare(strict_types=1);
namespace ImWiki\Controllers;
use ImWiki\Http\Request;use ImWiki\Repositories\UserRepository;use ImWiki\Security\Authorization;use ImWiki\Services\NotificationService;use ImWiki\View\View;use PDO;
final class SecurityDashboardController extends BaseController{
 public function index(Request $r):void{$uid=$this->requireAuth();if(!$this->authz->can($uid,'administration.access')){http_response_code(403);return;}$stats=[];$stats['failed_logins']=(int)$this->pdo->query("SELECT COUNT(*) FROM `{$this->prefix}login_history` WHERE success=0 AND created_at>=DATE_SUB(UTC_TIMESTAMP(),INTERVAL 24 HOUR)")->fetchColumn();$stats['without_2fa']=(int)$this->pdo->query("SELECT COUNT(*) FROM `{$this->prefix}users` u LEFT JOIN `{$this->prefix}user_totp` t ON t.user_id=u.id AND t.enabled=1 WHERE u.deleted_at IS NULL AND u.status='active' AND t.user_id IS NULL")->fetchColumn();$stats['api_tokens']=(int)$this->pdo->query("SELECT COUNT(*) FROM `{$this->prefix}api_tokens` WHERE revoked_at IS NULL AND (expires_at IS NULL OR expires_at>UTC_TIMESTAMP())")->fetchColumn();$stats['public_shares']=(int)$this->pdo->query("SELECT COUNT(*) FROM `{$this->prefix}public_shares` WHERE revoked_at IS NULL AND (expires_at IS NULL OR expires_at>UTC_TIMESTAMP())")->fetchColumn();$stats['old_sessions']=(int)$this->pdo->query("SELECT COUNT(*) FROM `{$this->prefix}user_sessions` WHERE revoked_at IS NULL AND last_seen_at<DATE_SUB(UTC_TIMESTAMP(),INTERVAL 30 DAY)")->fetchColumn();$failed=$this->pdo->query("SELECT login_identifier,ip_address,user_agent,created_at FROM `{$this->prefix}login_history` WHERE success=0 ORDER BY created_at DESC LIMIT 50")->fetchAll();echo $this->view->render('admin/security.php',$this->common(['stats'=>$stats,'failed'=>$failed]));}
}
